{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; its absence cannot be inferred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 apply to repeated-run precision, reinterpreting the test taker as a fixed AI system. Evidence for this precision question warrants 0, insufficient information, rather than 1, demonstrated inadequacy."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "An unrepeated evaluation provides no evidence of score stability or instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, repeated-run precision remains unsupported. The explicit absence of replication contradicts the procedural claim, but does not demonstrate unreliable scores; 0 rather than 1 applies to the missing precision evidence."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated scores were examined with the specified conditions held constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The reported range meets the stated stability definition."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the reported range as alternative precision evidence; 9.3 supplies the repeat-testing perspective. Stability is supported for this system and these conditions. This range is not a reliability coefficient, so coefficient anchors and human sample-size thresholds should not be applied mechanically."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly documents testing across repeated runs."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed variation exceeds the stated stability limit."
        }
      ],
      "instrument_review": "EFPA 9.7 identifies affirmative evidence of inadequate precision against the stated stability requirement, rather than missing evidence. A 1 is justified for that specific requirement; these findings do not establish precision for other systems or conditions."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no evidence about score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns installation and technical instructions, while 9.3 and 9.7 concern precision. Documentation additions do not substitute for precision evidence; the latter remains 0, insufficient information."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved a higher exact-grid score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 3.2 describes the observed scores; 10.1 and 10.5 require interpretations to match the measured domain and intended use. The narrow observed comparison is supported. Cross-domain validity is unestablished, without implying that the intended narrow use is inadequate."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed puzzle scores favor A under the reported conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended cross-domain use does not itself establish cross-domain validity."
        }
      ],
      "instrument_review": "EFPA 2.2, 6.1.1, 10.1, 10.3 and 10.5 require evidence supporting the stated broad interpretation. Such evidence is insufficient here. If broad-use validity receives a critical 0, EFPA's guidance restricts that use to research or exceptional circumstances with highly skilled experts; this is not proof that A lacks greater general intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence links those scores to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial supports higher correctness with A in the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 supports considering the randomized trial, and 10.3.2 addresses the relevant external correctness criterion. Preregistration, random allocation, blinded checking and reported uncertainty strengthen the local use argument. The 120 inspectors are trial participants, not 120 independent AI systems. The trial supports assistance effectiveness here, but does not by itself validate benchmark scores as predictors or establish safety benefits."
    }
  ],
  "closing_note": "No unresolved task ambiguity required clarification. All cases were assessed independently using relevant sections of the original EFPA model; full forms were expressly unnecessary. AI systems replace human test takers only where stated, and repeated runs are not human norm samples. Human sensory, motor, demographic and test-taker debriefing questions are inapplicable to these AI-system probes; human trial evidence remains relevant in C8. Missing applicable evidence is distinguished from demonstrated inadequacy. Statement labels are not EFPA ratings, and no aggregate quality score was calculated. EFPA model: EFPA (2025), version 5.0, https://www.efpa.eu/, CC BY-SA 4.0; application does not imply EFPA endorsement."
}
